samples.sql:
SELECT MAX(CAST(Free Meal Count (K-12) AS REAL) / Enrollment (K-12)) AS HighestEligibleFreeRate
FROM frpm
WHERE County = 'Alameda';

SELECT CDSCode
FROM frpm
WHERE (Enrollment (K-12) + Enrollment (Ages 5-17)) > 500;

SELECT COUNT(CDSCode) / 12 AS MonthlyAverage
FROM schools
WHERE County = 'Alameda' AND DOC = 52 AND strftime('%Y', OpenDate) = '1980';

SELECT t.* FROM trans t
JOIN account a ON t.account_id = a.account_id
WHERE a.district_id = 5;

SELECT element FROM atom
JOIN molecule ON atom.molecule_id = molecule.molecule_id
WHERE molecule.label = 'TR001' AND element IN ('Hg', 'As', 'Cd');

SELECT COUNT(atom_id) FROM atom 
JOIN molecule ON atom.molecule_id = molecule.molecule_id 
WHERE molecule.label = 'TR008' AND atom.element = 'c';

SELECT COUNT(*) 
FROM cards 
WHERE originalType = 'Summon - Angel' AND subtypes NOT LIKE '%Angel%';

SELECT CAST(COUNT(CASE WHEN language = 'French' AND (power IS NULL OR power = '*') THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(power IS NULL OR power = '*') AS percentage
FROM foreign_data
WHERE language = 'French';

SELECT COUNT(*) AS unknown_power_count
FROM cards
WHERE borderColor = 'White' AND (power = '*' OR power IS NULL);

SELECT EXISTS (
    SELECT 1
    FROM set_translations
    WHERE setCode = (
        SELECT setCode
        FROM sets
        WHERE name = 'Ancestor''s Chosen'
    )
    AND language = 'Korean'
) AS has_korean_translation;

SELECT EXISTS (
    SELECT 1
    FROM sets
    WHERE name = 'Angel of Mercy'
) AND EXISTS (
    SELECT 1
    FROM sets
    WHERE name = 'Angel of Mercy' AND mtgoCode IS NOT NULL
);

SELECT CAST(SUM(CASE WHEN cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM cards
WHERE name = 'Coldsnap';

SELECT p.Id, p.OwnerUserId
FROM posts p
WHERE p.Score > 60;

SELECT SUM(FavoriteCount) AS TotalFavoriteCount
FROM posts
WHERE UserId = 686 AND STRFTIME('%Y', CreationDate) = '2011';

SELECT SUM(Score) AS TotalScore
FROM posts
WHERE LasActivityDate LIKE '2010-07-19%';

SELECT CAST(COUNT(CASE WHEN T1.Reputation > 1000 AND YEAR(T2.CreationDate) = 2011 THEN T2.Id END) AS REAL) * 100 / COUNT(T2.Id) AS Percentage
FROM users AS T1
INNER JOIN posts AS T2 ON T1.Id = T2.OwnerUserId;

SELECT CAST(COUNT(Id) AS REAL) * 100 / (SELECT COUNT(Id) FROM users) AS percentage
FROM users
WHERE Age BETWEEN 13 AND 18;

SELECT COUNT(*) AS NumberOfPosts
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(*) FROM superhero AS T1
JOIN colour AS T2 ON T1.eye_colour_id = T2.id
WHERE T2.colour = 'Blue';

SELECT COUNT(*) FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id
WHERE T2.publisher_name = 'Marvel Comics';

SELECT COUNT(*) FROM superhero AS T1
JOIN colour AS T2 ON T1.hair_colour_id = T2.id
WHERE T2.colour = 'Blond';

SELECT COUNT(*) FROM superhero AS T1
JOIN race AS T2 ON T1.race_id = T2.id
WHERE T2.race = 'Vampire';

SELECT CAST(COUNT(CASE WHEN T1.alignment = 'Bad' AND T2.publisher_name = 'Marvel Comics' THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.id) AS percentage
FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id;

SELECT SUM(CASE WHEN publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN publisher_name = 'DC Comics' THEN 1 ELSE 0 END) AS difference
FROM publisher
JOIN superhero ON publisher.id = superhero.publisher_id;

SELECT AVG(T1.attribute_value) AS average_attribute_value
FROM hero_attribute AS T1
JOIN attribute AS T2 ON T1.attribute_id = T2.id;

SELECT AVG(weight_kg) AS average_weight
FROM superhero
WHERE gender_id = (SELECT id FROM gender WHERE gender = 'Female');

SELECT COUNT(*) FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id
WHERE T2.publisher_name = 'Dark Horse Comics';

SELECT COUNT(*) FROM superhero AS T1
JOIN alignment AS T2 ON T1.alignment_id = T2.id
WHERE T2.alignment = 'neutral';

SELECT COUNT(*) AS good_female_superheroes
FROM superhero
WHERE gender_id = 2 AND alignment_id = 1;

SELECT races.name FROM circuits
JOIN races ON circuits.circuitId = races.circuitId
WHERE circuits.country = 'Spain';

SELECT races.url FROM circuits
JOIN races ON circuits.circuitId = races.circuitId
WHERE circuits.name = 'Sepang International Circuit';

SELECT T1.nationality FROM drivers AS T1 INNER JOIN (
    SELECT driverId FROM results ORDER BY fastestLapSpeed DESC LIMIT 1
) AS T2 ON T1.driverId = T2.driverId

SELECT AVG(COUNT(*)) AS average_races_per_year
FROM (
  SELECT YEAR
  FROM races
  WHERE YEAR BETWEEN 2000 AND 2010
) AS yearly_races;

SELECT AVG(height) AS average_height
FROM Player
WHERE birthday BETWEEN '1990-01-01 00:00:00' AND '1995-12-31 23:59:59';

SELECT player_name
FROM Player
WHERE datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(birthday) > 34;

SELECT CAST(COUNT(CASE WHEN T1.height < 180 AND T2.overall_rating > 70 THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.id) AS percentage
FROM Player AS T1
JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id;

SELECT T1.ID FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID
WHERE T1.Birthday = '1982-04-01' AND T2.ALP < 300;

SELECT CAST(COUNT(ID) AS REAL) * 100 / COUNT(ID) AS Percentage
FROM Laboratory
WHERE GOT >= 60 AND Diagnosis = 'SLE';

SELECT MIN(T1.Birthday) AS OldestPatientBirthday
FROM Patient AS T1
WHERE T1.GLU > 180;

SELECT COUNT(DISTINCT event_name) / COUNT(event_id) AS average_attendance
FROM event
WHERE type = 'Meeting' AND YEAR(event_date) = 2020;

SELECT MAX(cost) AS most_expensive_cost
FROM expense
WHERE expense_description LIKE '%Club Event%' OR expense_description LIKE '%Support for Club Events%';

SELECT COUNT(*) FROM member AS T1
JOIN income AS T2 ON T1.member_id = T2.link_to_member
WHERE T1.first_name = 'Grant' AND T1.last_name = 'Gilmour';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT COUNT(*) AS num_extra_large_t_shirt
FROM member
WHERE position = 'Member' AND t_shirt_size = 'X-Large';

SELECT MAX(Consumption) AS HighestMonthlyConsumption
FROM yearmonth
WHERE SUBSTR(Date, 1, 4) = '2012';

SELECT AVG(Price) AS AveragePrice
FROM transactions_1k
WHERE Date LIKE '2012-01-%';
